{
  "name": "Testimonial Carousel",
  "slug": "testimonial-carousel",
  "description": "Display customer testimonials in a carousel",
  "category": "Content",
  "icon": "fa-quote-left",
  "fields": [
    {
      "name": "heading",
      "type": "text",
      "label": "Section Heading",
      "required": false
    },
    {
      "name": "testimonials",
      "type": "array",
      "label": "Testimonials",
      "required": true,
      "validation": {
        "minItems": 1
      }
    },
    {
      "name": "autoplay",
      "type": "boolean",
      "label": "Auto-play Carousel",
      "defaultValue": true
    }
  ]
}

{
  "description": "Display customer testimonials in a beautiful carousel with ratings"
}

{
  "metaDescription": "Updated description for the Home page",
  "metaKeywords": "steel, manufacturing, acero"
}

{
  "newParentId": "{{products_page_id}}"
}

{
  "pages": [
    {
      "_id": "{{products_page_id}}",
      "order": 1
    },
    {
      "_id": "{{about_page_id}}",
      "order": 2
    },
    {
      "_id": "{{home_page_id}}",
      "order": 3
    }
  ]
}

{
  "includeSections": false
}

{
  "sectionTypeSlug": "text_block",
  "order": 2,
  "content": {
    "heading": "About Our Company",
    "content": "<p>Acero Steel has been a leader in steel manufacturing since 1950. We pride ourselves on quality, innovation, and customer service.</p><p>Our state-of-the-art facilities produce a wide range of steel products for construction, automotive, and industrial applications.</p>",
    "alignment": "left"
  },
  "isVisible": true
}

{
  "sectionTypeSlug": "image_gallery",
  "order": 3,
  "content": {
    "images": [
      {
        "url": "https://images.unsplash.com/photo-1565043666747-69f6646db69-2",
        "caption": "Manufacturing facility",
        "alt": "Modern steel manufacturing plant"
      },
      {
        "url": "https://images.unsplash.com/photo-1565043666747-69f6646db69-3",
        "caption": "Quality control",
        "alt": "Quality inspection process"
      },
      {
        "url": "https://images.unsplash.com/photo-1565043666747-69f6646db69-4",
        "caption": "Finished products",
        "alt": "Steel products ready for delivery"
      }
    ],
    "layout": "grid",
    "columns": 3,
    "showCaptions": true
  },
  "isVisible": true
}

{
  "sectionTypeSlug": "features_grid",
  "order": 4,
  "content": {
    "heading": "Why Choose Acero Steel",
    "features": [
      {
        "title": "Quality Materials",
        "description": "We use only the highest grade steel",
        "icon": "check-circle"
      },
      {
        "title": "Fast Delivery",
        "description": "Quick turnaround on all orders",
        "icon": "truck"
      },
      {
        "title": "Expert Support",
        "description": "24/7 technical assistance",
        "icon": "headset"
      },
      {
        "title": "Competitive Pricing",
        "description": "Best value in the industry",
        "icon": "dollar-sign"
      }
    ],
    "columns": 4
  },
  "isVisible": true
}

{
  "sectionTypeSlug": "video",
  "order": 5,
  "content": {
    "title": "Virtual Factory Tour",
    "description": "Take a virtual tour of our manufacturing facility",
    "videoUrl": "https://www.youtube.com/embed/dQw4w9WgXcQ",
    "autoplay": false
  },
  "isVisible": true
}

{
  "sectionTypeSlug": "timeline",
  "order": 1,
  "content": {
    "heading": "Our Journey",
    "items": [
      {
        "year": "1950",
        "title": "Company Founded",
        "description": "Acero Steel was established in Pittsburgh"
      },
      {
        "year": "1975",
        "title": "Expansion",
        "description": "Opened second manufacturing facility"
      },
      {
        "year": "2000",
        "title": "Innovation",
        "description": "Introduced new steel alloy technology"
      },
      {
        "year": "2025",
        "title": "Industry Leader",
        "description": "Recognized as top steel manufacturer"
      }
    ]
  },
  "isVisible": true
}

{
  "content": {
    "title": "Welcome to Acero Steel - Updated",
    "subtitle": "Leading Manufacturer of Quality Steel Products Since 1950",
    "backgroundImage": "https://images.unsplash.com/photo-1565043666747-69f6646db69-1",
    "ctaButtonText": "Explore Products",
    "ctaButtonLink": "/products",
    "height": "large",
    "textAlignment": "center"
  }
}

